function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;').replace(/'/g,'&#39;');}
function t(id){return String(id||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());}
function normType(tp){tp=String(tp||'').toLowerCase();return ['line','bar','doughnut','pie'].includes(tp)?tp:'bar';}
function palette(tp,n){const b=['#1d4ed8','#0f766e','#dc2626','#f59e0b','#7c3aed','#0891b2','#16a34a','#db2777'];const c=Array.from({length:Math.max(n,1)},(_,i)=>b[i%b.length]);if(tp==='line')return {backgroundColor:'rgba(29,78,216,.2)',borderColor:'#1d4ed8',pointBackgroundColor:'#1d4ed8'};return {backgroundColor:c,borderColor:'#fff'};}
async function chartImg(ch){const labels=Array.isArray(ch.labels)?ch.labels:[];const data=Array.isArray(ch.data)?ch.data:[];const type=normType(ch.type);const cfg={type,data:{labels,datasets:[{label:ch.title||t(ch.id),data,...palette(type,labels.length),borderWidth:2,fill:type==='line'}]},options:{plugins:{legend:{position:'bottom'},title:{display:true,text:ch.title||t(ch.id)}}}};const u='https://quickchart.io/chart?width=900&height=420&format=png&c='+encodeURIComponent(JSON.stringify(cfg));const r=await fetch(u);if(!r.ok)throw new Error('quickchart');const ab=await r.arrayBuffer();const b64=Buffer.from(ab).toString('base64');return 'data:image/png;base64,'+b64;}
function kpisHtml(kpis){if(!Array.isArray(kpis)||!kpis.length)return '';return '<section class=\"section\"><h2>Indicadores</h2><div class=\"kpi-grid\">'+kpis.map(k=>'<div class=\"kpi-card\"><div class=\"kpi-label\">'+esc(k.label||t(k.id))+'</div><div class=\"kpi-value\">'+esc(k.value??'-')+'</div></div>').join('')+'</div></section>';}
function tablesHtml(tables){if(!Array.isArray(tables)||!tables.length)return '';return '<section class=\"section\"><h2>Tabelas</h2>'+tables.map(tb=>{const cols=Array.isArray(tb.columns)?tb.columns:[];const rows=Array.isArray(tb.rows)?tb.rows:[];const th=cols.map(c=>'<th>'+esc(c)+'</th>').join('');const tr=rows.map(r=>'<tr>'+((Array.isArray(r)?r:[]).map(c=>'<td>'+esc(c)+'</td>').join(''))+'</tr>').join('');return '<div class=\"table-wrap\"><h3>'+esc(tb.title||t(tb.id))+'</h3><table class=\"table\"><thead><tr>'+th+'</tr></thead><tbody>'+(tr||'<tr><td colspan=\"99\">Sem dados</td></tr>')+'</tbody></table></div>';}).join('')+'</section>';}
function filtersHtml(f){const e=Object.entries(f||{});if(!e.length)return '<p class=\"muted\">Sem filtros aplicados</p>';return '<ul class=\"filters\">'+e.map(([k,v])=>'<li><span>'+esc(t(k))+':</span> '+esc(typeof v==='object'?JSON.stringify(v):v)+'</li>').join('')+'</ul>';}
async function chartsHtml(charts){if(!Array.isArray(charts)||!charts.length)return '';const cards=[];for(const ch of charts){const title=esc(ch.title||t(ch.id));const labels=Array.isArray(ch.labels)?ch.labels:[];const data=Array.isArray(ch.data)?ch.data:[];let img='<p class=\"muted\">Nao foi possivel gerar imagem do grafico.</p>';try{img='<img class=\"chart-img\" src=\"'+await chartImg(ch)+'\" alt=\"'+title+'\" />';}catch(_){ }const rows=labels.map((lb,i)=>'<tr><td>'+esc(lb)+'</td><td class=\"num\">'+esc(data[i]??'-')+'</td></tr>').join('');cards.push('<div class=\"panel\"><div class=\"panel-title\">'+title+'</div><div class=\"panel-subtitle\">Tipo: '+esc(normType(ch.type))+'</div><div class=\"chart-wrap\">'+img+'</div><table class=\"table compact\"><thead><tr><th>Categoria</th><th class=\"num\">Valor</th></tr></thead><tbody>'+(rows||'<tr><td colspan=\"2\">Sem dados</td></tr>')+'</tbody></table></div>');}return '<section class=\"section\"><h2>Graficos</h2><div class=\"panel-grid\">'+cards.join('')+'</div></section>';}
async function main(){const root=$input.first().json||{};const input=(root.body&&typeof root.body==='object')?root.body:root;const report=input.report||{};const eventName=input.event||'nir_relatorio_manual';const generatedAt=report.generated_at||input.generated_at||new Date().toISOString();const msg=input.message||'Relatorio gerado manualmente no dashboard NIR.';const html='<!doctype html><html lang=\"pt-BR\"><head><meta charset=\"utf-8\" /><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" /><title>Relatorio NIR</title><style>body{margin:0;background:#eef2ff;font-family:Segoe UI,Arial,sans-serif;color:#0f172a}.container{max-width:980px;margin:0 auto;padding:28px 16px}.hero{background:linear-gradient(130deg,#0b3a84 0%,#0f766e 100%);color:#fff;border-radius:16px;padding:24px;box-shadow:0 10px 28px rgba(2,6,23,.2)}.hero h1{margin:0 0 8px;font-size:24px}.hero p{margin:4px 0;opacity:.95}.badge{display:inline-block;margin-top:8px;font-size:12px;letter-spacing:.04em;text-transform:uppercase;background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.24);border-radius:999px;padding:6px 10px}.section{margin-top:18px;background:#fff;border-radius:16px;padding:18px;border:1px solid #dbe5ff;box-shadow:0 4px 10px rgba(15,23,42,.05)}.section h2{margin:0 0 12px;color:#1e3a8a;font-size:18px}.section h3{margin:8px 0 10px;color:#334155}.kpi-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}.kpi-card{background:linear-gradient(180deg,#f8fafc 0%,#eef2ff 100%);border:1px solid #cbd5e1;border-radius:12px;padding:12px}.kpi-label{color:#334155;font-size:12px;text-transform:uppercase;letter-spacing:.03em}.kpi-value{color:#0f172a;font-size:24px;font-weight:700;margin-top:6px}.panel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:10px}.panel{border:1px solid #dbe5ff;border-radius:12px;padding:12px;background:#f8fafc}.panel-title{font-weight:700;color:#0f172a}.panel-subtitle{color:#64748b;font-size:12px;margin:2px 0 10px}.chart-wrap{margin:0 0 10px;border:1px solid #e2e8f0;border-radius:10px;background:#fff;padding:8px}.chart-img{width:100%;height:auto;display:block;border-radius:6px}.table-wrap{margin-top:12px;overflow-x:auto}.table{width:100%;border-collapse:collapse;min-width:420px}.table th,.table td{border-bottom:1px solid #e2e8f0;text-align:left;padding:8px;font-size:13px}.table th{background:#eff6ff;color:#1e3a8a}.table .num{text-align:right}.compact th,.compact td{padding:6px;font-size:12px}.filters{margin:0;padding-left:18px}.filters li{margin:4px 0;color:#334155}.filters span{color:#0f172a;font-weight:600}.muted{color:#64748b}.footer{margin-top:14px;font-size:12px;color:#64748b;text-align:center}</style></head><body><div class=\"container\"><div class=\"hero\"><h1>Central de Relatorios NIR</h1><p><strong>Data de geracao:</strong> '+esc(generatedAt)+'</p><p><strong>Mensagem:</strong> '+esc(msg)+'</p><span class=\"badge\">Evento: '+esc(eventName)+'</span></div><section class=\"section\"><h2>Filtros Aplicados</h2>'+filtersHtml(report.filters||{})+'</section>'+kpisHtml(report.kpis||[])+await chartsHtml(report.charts||[])+tablesHtml(report.tables||[])+'<div class=\"footer\">Relatorio enviado automaticamente via n8n.</div></div></body></html>';return [{json:{subject:'NIR | Relatorio '+generatedAt,emailHtml:html,event:eventName,generated_at:generatedAt}}];}
return await main();
